/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/discls/disclosure.do",
        ref: "dma_loadListReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods70401.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_102").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_docPageList_fmt_corpUsrNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_docPageList_fmt_corpUsrNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "kclicUsrTpId") ?? '') : '');
        if (v === 'LIST_CORP_DISCLS') { return "공시담당자"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.corpUsrNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.enterSearchForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.enterSearchForm = async function () {
    /* sdd-asis-lifecycle:begin enterSearchForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.searchList();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('ipt_fromDate').getValue()> $c.util.getComponent('ipt_toDate').getValue()) {
        await alertE('시작일자는 종료일자 이전 이어야 합니다.');
        return;
    }
    blockLoading();
    /* 수동 전환 필요: searchForm.submit() — as-is 자기제출(action 없음), 대체 tx 미정 */ await $c.win.alert("이 동작은 아직 전환되지 않았습니다(as-is 폼 «searchForm» 자기제출 — 대체 서버 호출 미정).");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fn_delete
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo
 * @returns
 * @hidden N
*/
scwin.fn_delete = function (applNo) {
    /* sdd-asis-lifecycle:begin fn_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    confirmF("삭제하시겠습니까?", async function() {
            await scwin.deleteDo(applNo);
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteDo
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo
 * @returns
 * @hidden N
*/
scwin.deleteDo = async function (applNo) {
    /* sdd-asis-lifecycle:begin fn_delete_do — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.searchForm || { elements: [] }).action = "/discls/searchDisclosureDocument.do?method=removeCompltDocument";
    $c.util.getComponent('dma_deleteDoReq').set('applNo', applNo);
    await scwin.tx_fn_delete_do();
    /* sdd-asis-lifecycle:end */
};


