 * @name scwin.documentSubmitDoDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.documentSubmitDoDone = async function (data) {
    /* sdd-asis-lifecycle:begin fn_document_submit_do_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */if (data.returnValue === 'Y') {
        await alertE("KIND 제출시스템으로 전송되었습니다.", function() {
                $c.win.setPageFrameSrc($c.win.getFrame(), null);
        });
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.documentSubmitDo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.documentSubmitDo = async function () {
    const r = await scwin.tx_fn_document_submit_do();
    try {
        scwin.documentSubmitDoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldods70401.fn_document_submit_do' });
    }
    return r;
};

